// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/organizations", wrapper.AdminListOrganizations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/organizations/{organizationId}", wrapper.AdminGetOrganization)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/organizations/{organizationId}/kyc/approve", wrapper.AdminApproveKYC)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/organizations/{organizationId}/kyc/reject", wrapper.AdminRejectKYC)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/applications/{applicationId}/approve", wrapper.AdminApproveApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/applications/{applicationId}/reject", wrapper.AdminRejectApplication)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/users", wrapper.AdminListUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/users/{userId}/block", wrapper.AdminBlockUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/users/{userId}/unblock", wrapper.AdminUnblockUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/aml/flags", wrapper.AdminListAMLFlags)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/admin/aml/flags/{flagId}/resolve", wrapper.AdminResolveAMLFlag)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/analytics/summary", wrapper.AdminAnalyticsSummary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/audit-log", wrapper.AdminListAuditLog)

	return m
}

