// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AdminListAMLFlags AML-флаги (rule-based скрининг)
	// (GET /admin/aml/flags)
	AdminListAMLFlags(ctx context.Context, request AdminListAMLFlagsRequestObject) (AdminListAMLFlagsResponseObject, error)

	// (POST /admin/aml/flags/{flagId}/resolve)
	AdminResolveAMLFlag(ctx context.Context, request AdminResolveAMLFlagRequestObject) (AdminResolveAMLFlagResponseObject, error)
	// AdminAnalyticsSummary Базовая аналитика — количество заявок, средний размер, топ-страны
	// (GET /admin/analytics/summary)
	AdminAnalyticsSummary(ctx context.Context, request AdminAnalyticsSummaryRequestObject) (AdminAnalyticsSummaryResponseObject, error)
	// AdminApproveApplication Одобрить заявку (moderation → published)
	// (POST /admin/applications/{applicationId}/approve)
	AdminApproveApplication(ctx context.Context, request AdminApproveApplicationRequestObject) (AdminApproveApplicationResponseObject, error)
	// AdminRejectApplication Вернуть заявку на доработку (moderation → rejected) с причиной
	// (POST /admin/applications/{applicationId}/reject)
	AdminRejectApplication(ctx context.Context, request AdminRejectApplicationRequestObject) (AdminRejectApplicationResponseObject, error)
	// AdminListAuditLog Журнал действий пользователей
	// (GET /admin/audit-log)
	AdminListAuditLog(ctx context.Context, request AdminListAuditLogRequestObject) (AdminListAuditLogResponseObject, error)
	// AdminListOrganizations Компании (очередь верификации — kyc_status=under_review)
	// (GET /admin/organizations)
	AdminListOrganizations(ctx context.Context, request AdminListOrganizationsRequestObject) (AdminListOrganizationsResponseObject, error)
	// AdminGetOrganization Полная карточка компании для проверки (документы, бенефициары, AML-флаги, пользователи)
	// (GET /admin/organizations/{organizationId})
	AdminGetOrganization(ctx context.Context, request AdminGetOrganizationRequestObject) (AdminGetOrganizationResponseObject, error)
	// AdminApproveKYC Верифицировать компанию (under_review → verified)
	// (POST /admin/organizations/{organizationId}/kyc/approve)
	AdminApproveKYC(ctx context.Context, request AdminApproveKYCRequestObject) (AdminApproveKYCResponseObject, error)
	// AdminRejectKYC Отклонить верификацию (under_review → rejected) с причиной
	// (POST /admin/organizations/{organizationId}/kyc/reject)
	AdminRejectKYC(ctx context.Context, request AdminRejectKYCRequestObject) (AdminRejectKYCResponseObject, error)

	// (GET /admin/users)
	AdminListUsers(ctx context.Context, request AdminListUsersRequestObject) (AdminListUsersResponseObject, error)
	// AdminBlockUser Заблокировать пользователя (инвалидирует все его сессии)
	// (POST /admin/users/{userId}/block)
	AdminBlockUser(ctx context.Context, request AdminBlockUserRequestObject) (AdminBlockUserResponseObject, error)

	// (POST /admin/users/{userId}/unblock)
	AdminUnblockUser(ctx context.Context, request AdminUnblockUserRequestObject) (AdminUnblockUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

